import json
import time
from taf.hw.hp.redfish.httpclient.ApiClient import ApiClient
from taf.hw.hp.redfish.httpclient.redfish_uri import UpdateServiceURI


class UpdateCommon(object):
    def __init__(self, configuration, access_token):
        self.httpclient = ApiClient(configuration, access_token)

    def get_firmware_inventory_collection(self, check_status=None, query_parameters=''):
        uri_params = query_parameters
        uri = UpdateServiceURI().firmware_inventory_uri + uri_params
        return self.httpclient.send_get_request(uri=uri, check_status=check_status)

    def upload_firmware_file_to_repository(self, firmware_file_name, http_server_ip, check_status=None):
        uri = UpdateServiceURI().add_file_uri
        data = {"UpdateTarget": False,
                "TPMOverrideFlag": True,
                "UpdateRepository": True,
                "ComponentFileName": firmware_file_name,
                "ImageURI": "http://%s/%s" % (http_server_ip, firmware_file_name)}
        return self.httpclient.send_post_request(uri=uri, check_status=check_status, data=json.dumps(data),
                                                 headers={"Content-Type": "application/json"})

    def interrogate_firmware_file_in_repository(self, check_status=None):
        uri_params = '?$expand=.'
        uri = UpdateServiceURI().component_repository_uri + uri_params
        return self.httpclient.send_get_request(uri=uri, check_status=check_status)

    def upgrade_component_file(self, firmware_file_name, updatable_by=True, check_status=None):
        updatable_by_value = ["Bmc"] if updatable_by else ["Bmc", "Uefi"]
        uri = UpdateServiceURI().update_file_uri
        time_stamp = time.strftime('%Y%m%d%H%M%S', time.localtime())
        data = {"Name": "Firmware Package Upgrade_%s" % time_stamp,
                "Command": "ApplyUpdate",
                "Filename": firmware_file_name,
                "UpdatableBy": updatable_by_value,
                "TPMOverride": True,
                "StartAfter": "",
                "Expire": ""}
        result = self.httpclient.send_post_request(uri=uri, check_status=check_status, data=json.dumps(data),
                                                 headers={"Content-Type": "application/json"})
        return result['Id']

    def interrogate_upgrade_task_in_queue(self, queue_id, check_status=None):
        uri = UpdateServiceURI().queue_info_uri.format(queue_id=queue_id)
        return self.httpclient.send_get_request(uri=uri, check_status=check_status)

    def delete_job_in_the_queue(self, queue_id, check_status=None):
        uri = UpdateServiceURI().queue_info_uri.format(queue_id=queue_id)
        return self.httpclient.send_delete_request(uri=uri, check_status=check_status)
